<?php
declare(strict_types=1);
require_once __DIR__ . '/accounts_common.php';
$user=qbook_require_user();qbook_require_role($user,['ADMIN']);production_require_method('GET');
accounts_endpoint(function(): array {$db=production_db();$rows=$db->query("SELECT e.*,r.reference_no,b.name AS bank_name,j.reference_no AS original_journal_reference,rj.reference_no AS reversal_journal_reference,(SELECT COUNT(*) FROM qbook_financial_evidence v WHERE v.source_type='GENERAL_EXPENSE' AND v.source_record_id=e.id) AS evidence_count FROM qbook_general_expenses e LEFT JOIN qbook_general_expense_references r ON r.expense_id=e.id LEFT JOIN qbook_bank_accounts b ON b.id=e.bank_account_id LEFT JOIN qbook_financial_journals j ON j.id=e.journal_id LEFT JOIN qbook_financial_journals rj ON rj.id=e.reversal_journal_id ORDER BY COALESCE(e.expense_date,DATE(e.created_at)) DESC,e.id DESC LIMIT 500")->fetchAll();$line=$db->prepare("SELECT l.*,a.code AS account_code,a.name AS category,cc.code AS cost_centre_code,cc.name AS cost_centre_name,c.name AS client_name,p.name AS project_name,m.code AS mixer_code FROM qbook_general_expense_lines l JOIN qbook_accounts_chart a ON a.id=l.expense_account_id LEFT JOIN qbook_cost_centres cc ON cc.id=l.cost_centre_id LEFT JOIN qbook_clients c ON c.id=l.client_id LEFT JOIN qbook_projects p ON p.id=l.project_id LEFT JOIN qbook_mixers m ON m.id=l.mixer_id WHERE l.expense_id=? ORDER BY l.line_no");foreach($rows as &$row){$row['reference_no']=accounts_general_expense_reference($row['reference_no']);$line->execute([(int)$row['id']]);$row['lines']=$line->fetchAll();}unset($row);return ['expenses'=>$rows];});
